// Narration, snapshot and question composers.
// Everything here is assembled from the archive's own fields. No text is
// generated by a model, so every sentence a listener hears can be traced back
// to the research entry it came from.

const NA = /^(not applicable|n\/a|none|nil|not documented|unknown)\b/i;

export function has(v) {
  return typeof v === "string" && v.trim().length > 2 && !NA.test(v.trim());
}

// "Handia (হান্ডি) / Handi" -> "Handia"; "Eu (ইউ)" -> "Eu"
export function shortName(food = "") {
  let s = food.split(/\s+\(|\s+\/\s+|\s+—\s+/)[0].trim();
  if (s.length > 42) s = s.slice(0, 40).replace(/\s+\S*$/, "") + "…";
  return s || food;
}

// Lower-case SHOUTED words (keeps short acronyms such as PVTG, NTFP, CE)
function softenCaps(s) {
  return s
    .replace(/\b[A-Z][A-Z'’-]+(?:\s+[A-Z][A-Z'’-]+)+\b/g, (w) => w.toLowerCase())
    .replace(/\b([A-Z][A-Z'’-]{4,})\b/g, (w) => w.toLowerCase());
}

// Clean archive shorthand so it reads and sounds like prose
export function prose(text = "", { citations = false } = {}) {
  let s = String(text).replace(/\s*\n+\s*/g, ". ");
  if (!citations) s = s.replace(/\s*\((?:[^()]*?\b(?:1[89]|20)\d{2}[a-z]?)\)/g, "");
  s = s
    .replace(/\(\d{1,2}\)\s*/g, "")
    .replace(/\s*→\s*/g, ", then ")
    .replace(/\s+=\s+/g, " is ")
    .replace(/\s+&\s+/g, " and ")
    .replace(/\be\.g\.,?/gi, "for example")
    .replace(/\bi\.e\.,?/gi, "that is")
    .replace(/\bapprox\.?\s/gi, "about ")
    .replace(/\bhrs\b/gi, "hours")
    .replace(/\bc\.\s*(?=\d)/g, "around ")
    .replace(/(\w)\s+\/\s+(\w)/g, "$1 or $2")
    .replace(/\.\s*\./g, ".")
    .replace(/\s{2,}/g, " ")
    .trim();
  s = softenCaps(s);
  // "Origin myth: …" style labels: capitalise after lowering
  s = s.replace(/(^|[.!?]\s+)([a-z])/g, (m, a, b) => a + b.toUpperCase());
  return s;
}

const ABBR = /\b(?:et al|Dr|Mr|Mrs|St|No|vs|Fig|cf|Vol|ed|Ltd|approx|Govt|viz)\.$/i;

export function sentences(text = "") {
  const s = String(text).trim();
  if (!s) return [];
  const parts = [];
  let buf = "";
  const tokens = s.split(/(?<=[.!?।])\s+/);
  for (const t of tokens) {
    buf = buf ? buf + " " + t : t;
    if (ABBR.test(buf) || /\b[A-Z]\.$/.test(buf) || /\d\.$/.test(buf) && /^\d/.test(t)) continue;
    parts.push(buf);
    buf = "";
  }
  if (buf) parts.push(buf);
  return parts
    .map((p) => p.trim())
    .filter((p) => p.length > 1)
    .map((p) => (/[.!?।…'"’”)]$/.test(p) ? p : p + "."));
}

export function firstSentences(text, n = 1, opts) {
  if (!has(text)) return [];
  return sentences(prose(text, opts)).slice(0, n);
}

function lowerFirst(s) {
  return s && /^[A-Z][a-z]/.test(s) ? s[0].toLowerCase() + s.slice(1) : s;
}

function listJoin(items, and = "and") {
  const a = items.filter(Boolean);
  if (a.length <= 1) return a[0] || "";
  return a.slice(0, -1).join(", ") + ` ${and} ` + a[a.length - 1];
}

function article(word) {
  return /^[aeiou]/i.test(word) ? "an" : "a";
}

function tribesPhrase(e) {
  const t = (e.tribes || []).filter((x) => !/pan-west|multi-tribe/i.test(x));
  if (!t.length) return "tribal communities of West Bengal";
  if (t.length === 1) return `${t[0]} people`;
  return `${listJoin(t)} peoples`;
}

function districtPhrase(e) {
  const d = (e.district || "").trim();
  if (!d || /multiple|pan-west|rural/i.test(d)) return "rural West Bengal";
  if (/[/,]/.test(d) || /border/i.test(d)) return `the ${d.replace(/\s*\/\s*/g, " and ")} region`;
  return `${d.replace(/\s*\(.*\)/, "")} district of West Bengal`;
}

function placeName(e) {
  const bv = (e.block_village || "").split(/[;—(]/)[0].trim();
  if (!bv || /^multiple|^various|^survey/i.test(bv)) return "";
  return bv.replace(/,\s*$/, "");
}

function categoryPhrase(e) {
  const c = (e.category || "").replace(/\s*\(.*?\)\s*/g, " ").replace(/\s+/g, " ").trim();
  if (!c) return "";
  return c
    .split(/\s*\/\s*/)
    .slice(0, 2)
    .join(" or ")
    .split(" ")
    .map((w) => (/[A-Z].*[A-Z]/.test(w) ? w : w.toLowerCase()))
    .join(" ");
}

// ---------------------------------------------------------------- Tour
// Returns paragraphs, each an array of sentences.
export function composeTour(e) {
  const short = shortName(e.food_name);
  const P = [];
  const push = (arr) => {
    const a = arr.flat().filter(Boolean);
    if (a.length) P.push(a);
  };

  const place = placeName(e);
  const where = place ? `Welcome to ${place}, in ${districtPhrase(e)}.` : `Welcome to ${districtPhrase(e)}.`;
  const eco = has(e.ecology) && !/multiple/i.test(e.ecology) ? `Look around you: ${lowerFirst(prose(e.ecology).replace(/\.$/, ""))}.` : "";
  const who = `This is the country of the ${tribesPhrase(e)}${e.pvtg && /yes/i.test(e.pvtg_status) && !/mixed/i.test(e.pvtg_status) ? ", among West Bengal's Particularly Vulnerable Tribal Groups" : ""}.`;
  push([where, eco, who]);

  const local = (e.local_name || "").split(/[,;]/)[0].replace(/\s*\(.*?\)/g, "").trim();
  const sameName = local.toLowerCase().startsWith(short.split(" ")[0].toLowerCase()) || short.toLowerCase().startsWith(local.toLowerCase());
  const alsoCalled = local && !sameName && !/community|nursery/i.test(local) ? `, also called ${local}` : "";
  const cat = categoryPhrase(e);
  const notDish = /not a (single dish|food item)/i.test(e.category);
  const intro = notDish
    ? `Our landmark is ${short}${alsoCalled}. It is not a single dish, and the archive files it as ${article(cat)} ${cat}.`
    : `Our landmark is ${short}${alsoCalled}${cat ? `, ${article(cat)} ${cat}` : ""}.`;
  const ing = has(e.ingredients) ? `What goes into it? ${prose(e.ingredients).replace(/\.$/, "")}.` : "";
  push([intro, ing]);

  const method = firstSentences(e.culinary_technology, 3);
  const tools = has(e.vessel_tool) ? `The tools matter too: ${prose(e.vessel_tool).replace(/\.$/, "")}.` : "";
  if (method.length) push([notDish ? "Here is what it involves." : "Here is how it is made.", method, tools]);

  const season = firstSentences(e.season, 1);
  const scarce = firstSentences(e.scarcity, 1);
  if (season.length || scarce.length) push([season.length ? `Its season: ${lowerFirst(season[0])}` : "", scarce]);

  const memory = firstSentences(e.cultural_memory, 2);
  const ritual = has(e.ritual_use) && !/^not\b/i.test(e.ritual_use) ? firstSentences(e.ritual_use, 1) : [];
  if (memory.length || ritual.length) push(["Now listen to the memory it carries.", memory, ritual]);

  const med = firstSentences(e.medicinal_value, 2);
  if (med.length) push(["The archive also records its healing side.", med]);

  const lost = firstSentences(e.lost_traditions, 2);
  if (lost.length) push(["But this knowledge is fragile.", lost]);

  if (e.origin && has(e.origin.geographic_origin)) push(["Its roots run deep.", firstSentences(e.origin.geographic_origin, 2)]);

  const sig = firstSentences(e.cultural_significance, 2);
  const world = /^tribal communities/.test(tribesPhrase(e)) ? "West Bengal's tribal" : `the ${tribesPhrase(e).replace(/ peoples?$/, "")}`;
  push([sig, `Remember ${short}, and you carry a little of ${world} world with you.`]);
  return P;
}

// ---------------------------------------------------------------- Questions
function qaBank(e) {
  const short = shortName(e.food_name);
  const bank = {};
  const loc = placeName(e) ? `${placeName(e)}, in ${districtPhrase(e)}` : districtPhrase(e);
  bank.who = {
    q: `Which community keeps ${short} alive, and where?`,
    a: [`${short} belongs to the ${tribesPhrase(e)}, documented in ${loc}.`, e.pvtg ? "The entry is marked as part of a Particularly Vulnerable Tribal Group's heritage." : "", (/multiple/i.test(e.ecology) ? [] : firstSentences(e.ecology, 1)).map((s) => `The landscape: ${lowerFirst(s)}`)].flat().filter(Boolean).join(" "),
  };
  if (has(e.ingredients)) bank.ing = { q: `What goes into ${short}?`, a: prose(e.ingredients, { citations: true }) };
  const m = firstSentences(e.culinary_technology, 2, { citations: true });
  if (m.length) bank.how = { q: /not a/i.test(e.category) ? `What does ${short} involve in practice?` : `How is ${short} prepared?`, a: m.join(" ") + (has(e.vessel_tool) ? ` Tools: ${prose(e.vessel_tool)}` : "") };
  const s = [...firstSentences(e.season, 1), ...firstSentences(e.scarcity, 1)];
  if (s.length) bank.when = { q: `When is ${short} made or eaten, and does it ever grow scarce?`, a: s.join(" ") };
  const mem = [...firstSentences(e.cultural_memory, 2, { citations: true }), ...(has(e.ritual_use) && !/^not\b/i.test(e.ritual_use) ? firstSentences(e.ritual_use, 1) : [])];
  if (mem.length) bank.mem = { q: `What story, memory or ritual surrounds ${short}?`, a: mem.join(" ") };
  const sac = firstSentences(e.sacred_foods, 2);
  if (sac.length) bank.sac = { q: `Is ${short} offered to deities or ancestors?`, a: sac.join(" ") };
  const med = firstSentences(e.medicinal_value, 2, { citations: true });
  if (med.length) bank.med = { q: `What healing or nutritional value is recorded for ${short}?`, a: med.join(" ") };
  const lost = firstSentences(e.lost_traditions, 2, { citations: true });
  if (lost.length) bank.lost = { q: `What is at risk of being lost around ${short}, and why?`, a: lost.join(" ") };
  if (e.origin && has(e.origin.geographic_origin)) bank.orig = { q: `Where did ${short} come from?`, a: firstSentences(e.origin.geographic_origin, 2, { citations: true }).join(" ") };
  const sig = firstSentences(e.cultural_significance, 2, { citations: true });
  if (sig.length) bank.sig = { q: `Why does ${short} matter beyond nourishment?`, a: sig.join(" ") };
  return bank;
}

const ORDER = ["who", "how", "mem", "lost", "orig", "sig", "ing", "when", "sac", "med"];

export function composeQuestions(e) {
  const bank = qaBank(e);
  const out = [];
  for (const k of ORDER) {
    if (bank[k] && out.length < 5) out.push({ ...bank[k], kind: k, id: e.entry_id });
  }
  return out;
}

// ---------------------------------------------------------------- Snapshot
function shuffle(arr, seed) {
  const a = arr.slice();
  let s = seed % 2147483647 || 1;
  for (let i = a.length - 1; i > 0; i--) {
    s = (s * 16807) % 2147483647;
    const j = s % (i + 1);
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function topCounts(list) {
  const m = new Map();
  for (const x of list) m.set(x, (m.get(x) || 0) + 1);
  return [...m.entries()].sort((a, b) => b[1] - a[1]).map((x) => x[0]);
}

const NORTH = new Set(["Darjeeling", "Jalpaiguri", "Alipurduar", "Cooch Behar", "Kalimpong"]);

export function composeSnapshot(visible, placeCount, seed = Date.now()) {
  if (!visible.length) return null;
  const pool = shuffle(visible, seed);
  const dists = topCounts(visible.flatMap((e) => e.districts));
  const tribes = topCounts(visible.flatMap((e) => e.tribes)).filter((t) => !/pan-west|multi-tribe/i.test(t));
  const groups = topCounts(visible.map((e) => e.group));
  const north = dists.some((d) => NORTH.has(d));
  const south = dists.some((d) => !NORTH.has(d));

  const P = [];
  let region;
  if (dists.length >= 6 && north && south) region = "most of West Bengal, from the Darjeeling hills and the Dooars down to the Junglemahal forests and the Rarh plateau";
  else if (dists.length) region = `${listJoin(dists.slice(0, 3))}${dists.length > 3 ? " and their neighbours" : ""}`;
  else region = "West Bengal's tribal heartland";
  const tr = tribes.slice(0, 5);
  P.push([
    `From this height you are looking over ${region}.`,
    `${visible.length} food ${visible.length === 1 ? "tradition is" : "traditions are"} mapped in view across ${placeCount} ${placeCount === 1 ? "place" : "places"}, kept by the ${listJoin(tr)}${tribes.length > 5 ? ` and ${tribes.length - 5} more ${tribes.length - 5 === 1 ? "community" : "communities"}` : ""}.`,
  ]);

  const pvt = topCounts(visible.filter((e) => e.pvtg && /yes/i.test(e.pvtg_status)).flatMap((e) => e.tribes)).filter((t) => ["Toto", "Lodha", "Birhor", "Kheria Sabar"].includes(t));
  if (pvt.length) P.push([`The ${listJoin(pvt)} ${pvt.length === 1 ? "are" : "are each"} a Particularly Vulnerable Tribal Group, and their foods carry special archival priority.`]);

  const g = groups.slice(0, 2);
  const ex = pool.filter((e) => g.includes(e.group)).slice(0, 3).map((e) => shortName(e.food_name));
  if (g.length) P.push([`The view leans toward ${listJoin(g.map((x) => x.toLowerCase().replace(/ & /g, " and ").replace(/\s*\(ntfp\)/, "")))}${ex.length ? `: think of ${listJoin(ex)}` : ""}.`]);

  const ecos = [];
  for (const e of pool) {
    if (!has(e.ecology) || /multiple/i.test(e.ecology)) continue;
    const c = prose(e.ecology).split(/,|;/)[0].trim().replace(/\.$/, "");
    if (c && !ecos.some((x) => x.toLowerCase() === c.toLowerCase())) ecos.push(c);
    if (ecos.length === 2) break;
  }
  if (ecos.length === 2) P.push([`The land shifts between ${lowerFirst(ecos[0])} and ${lowerFirst(ecos[1])}.`]);
  else if (ecos.length === 1) P.push([`The land here is ${lowerFirst(ecos[0])}.`]);

  const mem = pool.find((e) => firstSentences(e.cultural_memory, 1).length);
  if (mem) P.push([`${shortName(mem.food_name)}, from the ${tribesPhrase(mem)}, carries a story.`, firstSentences(mem.cultural_memory, 1)].flat());
  const lost = pool.find((e) => e !== mem && firstSentences(e.lost_traditions, 1).length);
  if (lost) P.push([`And something is slipping away. Of ${shortName(lost.food_name)}, the archive notes:`, firstSentences(lost.lost_traditions, 1)].flat());
  P.push(["Each medallion here is a kitchen, a forest path and a memory. Open one, and listen."]);

  // five questions, one per entry, rotating the kind of question
  const kinds = ["who", "how", "mem", "lost", "sig", "orig", "when", "med", "ing", "sac"];
  const qs = [];
  let k = seed % kinds.length;
  for (const e of pool) {
    if (qs.length >= 5) break;
    const bank = qaBank(e);
    for (let t = 0; t < kinds.length; t++) {
      const kind = kinds[(k + t) % kinds.length];
      if (bank[kind]) {
        qs.push({ ...bank[kind], kind, id: e.entry_id });
        k = (k + t + 1) % kinds.length;
        break;
      }
    }
  }
  return { paragraphs: P, questions: qs, tribes, dists, groups };
}

// ---------------------------------------------------------------- Origins formatting
// Splits an origin narrative into blocks: {head, text, chain[]}
export function originBlocks(text = "") {
  const blocks = [];
  for (const raw of String(text).split(/\n\s*\n/)) {
    const lines = raw.split("\n").map((l) => l.trim()).filter(Boolean);
    if (!lines.length) continue;
    const block = { head: "", text: "", chain: [] };
    const first = lines[0];
    const m = first.match(/^([A-Z0-9][A-Z0-9 ,'’&()\-—/.]{3,90}):\s*(.*)$/);
    if (m && m[1] === m[1].toUpperCase()) {
      const small = /^(and|the|of|in|to|a|an|from|as|on|for|or|by|with|at)$/;
      block.head = m[1].toLowerCase().split(" ").map((w, i) => (i && small.test(w) ? w : w.replace(/^([a-z])/, (c) => c.toUpperCase()))).join(" ");
      if (m[2]) block.text = m[2];
    } else block.text = first;
    for (const l of lines.slice(1)) {
      if (/^→/.test(l)) block.chain.push(l.replace(/^→\s*/, ""));
      else block.text += (block.text ? " " : "") + l;
    }
    blocks.push(block);
  }
  return blocks;
}

export function timelineItems(text = "") {
  const parts = String(text).split(/(?<=\.)\s+(?=[^.:]{1,48}:\s)/);
  const merged = [];
  for (const p of parts) {
    if (merged.length && merged[merged.length - 1].length < 5) merged[merged.length - 1] += " " + p;
    else merged.push(p);
  }
  const items = merged.map((p) => {
    const i = p.indexOf(":");
    if (i > 0 && i < 50) return { when: p.slice(0, i).trim(), what: p.slice(i + 1).trim() };
    return { when: "", what: p.trim() };
  });
  return items.length > 1 ? items : null;
}
